  en: { none: '(no additional focus)', authors: 'AUTHORS', verifiedDescription: 'VERIFIED DESCRIPTION', retryInvalidJson: 'The attempt did not produce usable structured JSON', retryReturnObject: 'Return the complete object again with paragraphs, claims, text, and evidence.', retryShorten: 'Shorten each claim and keep only exact EVIDENCE IDs.' },
