export function chapterPromptPack(language: PromptLanguage = 'es'): ChapterPromptPack { return CHAPTER_PROMPT_PACKS[language] ?? CHAPTER_PROMPT_PACKS.es; }

const SECTION_SCHEMA = '{"title":"","summary":"","role":"","concepts":[""],"claims":[{"text":"","support_quote":"literal quote from the fragment","page":"p. N or null","confidence":0.0}]}';
const PROFILE_SCHEMA = '{"source_language":"es","overview":"","fields":[{"kind":"thesis","text":"","confidence":0.0,"centrality":0.0,"support_quote":"literal quote already present in sections","page":"p. N or null"}]}';
const AUDIT_SCHEMA = '{"passed":true,"score":0.0,"issues":[""],"field_fixes":[{"index":0,"text":"","support_quote":""}],"overview":""}';
export const DOCUMENT_PROFILE_PROMPT_PACKS: Record<PromptLanguage, DocumentProfilePromptPack> = {
  es: { section: `Analiza íntegramente el fragmento de una sección académica. Devuelve JSON estricto: ${SECTION_SCHEMA}. La cita debe copiarse literalmente; distingue argumento central de menciones incidentales; no inventes.`, reduce: `Fusiona análisis parciales de UNA misma sección. Devuelve el mismo JSON estricto. Conserva solo afirmaciones centrales y sus citas literales ya presentes; no inventes citas.`, sectionAudit: `Audita un análisis de sección contra el fragmento completo. Devuelve JSON estricto: {"passed":true,"issues":[""],"analysis":${SECTION_SCHEMA}}. Comprueba que summary, role y claims no contradigan el fragmento, distingan tesis de menciones incidentales y que toda support_quote sea literal. Si passed=false, devuelve en analysis una versión íntegra corregida usando solo el fragmento; si true, repite sin cambios. No inventes.`, profile: `Construye una ficha verificable de una obra a partir de sus secciones ya analizadas. Devuelve JSON estricto: ${PROFILE_SCHEMA}. Kinds permitidos: object,problem,question,thesis,argument,method,sources,concept,temporal_scope,geographic_scope,disciplinary_scope,structure,conclusion,contribution,limitation,genre,audience,positioning,original_abstract. Incluye varios argument/concept cuando proceda; omite lo que la obra no permita afirmar; toda afirmación debe tener apoyo literal; no uses conocimiento externo.`, audit: `Audita una ficha documental contra su estructura y apoyos literales. Devuelve JSON estricto: ${AUDIT_SCHEMA}. Comprueba tesis central, método, fuentes, alcance, conclusiones, centralidad frente a menciones incidentales y fidelidad de cada apoyo. passed solo puede ser true sin errores sustantivos; no inventes.`, repair: `Repara la ficha usando exclusivamente los análisis de sección y los problemas del auditor. Devuelve exactamente el esquema original. Elimina campos no apoyados. Cada support_quote debe copiar sin alterar una palabra uno de los support_quote presentes en claims; no lo resumas, traduzcas ni parafrasees.` },
  en: { section: `Analyse the academic section fragment in full. Return strict JSON: ${SECTION_SCHEMA}. Copy the quote literally; distinguish the central argument from incidental mentions; invent nothing.`, reduce: `Merge partial analyses of ONE section. Return the same strict JSON. Keep only central claims and their literal quotes already present; invent no quotes.`, sectionAudit: `Audit a section analysis against its complete supporting fragment. Return strict JSON: {"passed":true,"issues":[""],"analysis":${SECTION_SCHEMA}}. Check that summary, role, and claims do not contradict the fragment, distinguish thesis from incidental mentions, and every support_quote is literal. If passed=false, return a complete corrected analysis using only the fragment; if true, repeat the received analysis unchanged. Invent nothing.`, profile: `Build a verifiable work profile from its analysed sections. Return strict JSON: ${PROFILE_SCHEMA}. Allowed kinds: object,problem,question,thesis,argument,method,sources,concept,temporal_scope,geographic_scope,disciplinary_scope,structure,conclusion,contribution,limitation,genre,audience,positioning,original_abstract. Include multiple argument/concept fields where appropriate; omit unsupported claims; every assertion needs literal support; use no outside knowledge.`, audit: `Audit a document profile against its structure and literal support. Return strict JSON: ${AUDIT_SCHEMA}. Check central thesis, method, sources, scope, conclusions, centrality versus incidental mentions, and fidelity of every support. passed may be true only without substantive errors; invent nothing.`, repair: `Repair the profile using only section analyses and auditor issues. Return exactly the original profile schema. Remove unsupported fields. Every support_quote must copy, without changing a word, one support_quote already present in claims; do not summarise, translate, or paraphrase it.` },
  fr: { section: `Analysez intégralement le fragment d’une section académique. Retournez le JSON strict : ${SECTION_SCHEMA}. Copiez la citation littéralement ; distinguez l’argument central des mentions incidentes ; n’inventez rien.`, reduce: `Fusionnez les analyses partielles d’UNE section. Retournez le même JSON strict. Conservez seulement les affirmations centrales et leurs citations déjà présentes ; n’inventez aucune citation.`, sectionAudit: `Auditez une analyse de section contre son fragment complet. Retournez le JSON strict : {"passed":true,"issues":[""],"analysis":${SECTION_SCHEMA}}. Vérifiez que summary, role et claims ne contredisent pas le fragment, distinguent la thèse des mentions incidentes et que chaque support_quote est littéral. Si passed=false, renvoyez une analyse complète corrigée avec le seul fragment ; sinon répétez l’analyse reçue. N’inventez rien.`, profile: `Construisez une fiche vérifiable d’une œuvre à partir de ses sections analysées. Retournez le JSON strict : ${PROFILE_SCHEMA}. Kinds autorisés : object,problem,question,thesis,argument,method,sources,concept,temporal_scope,geographic_scope,disciplinary_scope,structure,conclusion,contribution,limitation,genre,audience,positioning,original_abstract. Ajoutez plusieurs champs argument/concept si nécessaire ; omettez ce qui n’est pas affirmable ; chaque affirmation doit avoir un appui littéral ; aucune connaissance externe.`, audit: `Auditez une fiche documentaire contre sa structure et ses appuis littéraux. Retournez le JSON strict : ${AUDIT_SCHEMA}. Vérifiez thèse, méthode, sources, portée, conclusions, centralité et fidélité de chaque appui. passed n’est true qu’en l’absence d’erreur substantielle ; n’inventez rien.`, repair: `Réparez la fiche avec les seules analyses de section et les problèmes de l’auditeur. Retournez exactement le schéma original. Supprimez les champs non étayés. Chaque support_quote doit recopier sans modification une citation déjà présente dans claims ; ne la résumez, traduisez ni paraphrasez pas.` },
  de: { section: `Analysieren Sie den akademischen Abschnitt vollständig. Geben Sie striktes JSON aus: ${SECTION_SCHEMA}. Kopieren Sie das Zitat wörtlich; unterscheiden Sie das Hauptargument von beiläufigen Erwähnungen; erfinden Sie nichts.`, reduce: `Führen Sie Teilauswertungen EINER Sektion zusammen. Geben Sie dasselbe strikte JSON aus. Bewahren Sie nur zentrale Aussagen und bereits vorhandene wörtliche Zitate; erfinden Sie keine Zitate.`, sectionAudit: `Prüfen Sie eine Sektionsanalyse anhand des vollständigen Abschnitts. Geben Sie striktes JSON aus: {"passed":true,"issues":[""],"analysis":${SECTION_SCHEMA}}. Prüfen Sie, dass summary, role und claims den Abschnitt nicht widersprechen, These und Nebenbemerkungen trennen und jedes support_quote wörtlich ist. Bei passed=false eine vollständige korrigierte Analyse nur aus dem Abschnitt zurückgeben; bei true unverändert wiederholen. Nichts erfinden.`, profile: `Erstellen Sie aus analysierten Sektionen ein überprüfbares Werkprofil. Geben Sie striktes JSON aus: ${PROFILE_SCHEMA}. Erlaubte kinds: object,problem,question,thesis,argument,method,sources,concept,temporal_scope,geographic_scope,disciplinary_scope,structure,conclusion,contribution,limitation,genre,audience,positioning,original_abstract. Mehrere argument/concept-Felder bei Bedarf; unbelegtes weglassen; jede Aussage braucht wörtliche Unterstützung; kein Außenwissen.`, audit: `Prüfen Sie ein Dokumentprofil anhand seiner Struktur und wörtlichen Belege. Geben Sie striktes JSON aus: ${AUDIT_SCHEMA}. Prüfen Sie zentrale These, Methode, Quellen, Umfang, Schlussfolgerungen, Zentralität und jeden Beleg. passed darf nur ohne wesentliche Fehler true sein; nichts erfinden.`, repair: `Reparieren Sie das Profil ausschließlich anhand von Sektionsanalysen und Auditorproblemen. Geben Sie exakt das ursprüngliche Schema aus. Entfernen Sie unbelegte Felder. Jedes support_quote muss wortgetreu aus einem vorhandenen support_quote in claims stammen; nicht zusammenfassen, übersetzen oder paraphrasieren.` },
  pt: { section: `Analisa integralmente o fragmento de uma secção académica. Devolve JSON estrito: ${SECTION_SCHEMA}. Copia a citação literalmente; distingue o argumento central de menções incidentais; não inventes.`, reduce: `Funde análises parciais de UMA secção. Devolve o mesmo JSON estrito. Conserva apenas afirmações centrais e citações literais já presentes; não inventes citações.`, sectionAudit: `Audita uma análise de secção contra o fragmento completo. Devolve JSON estrito: {"passed":true,"issues":[""],"analysis":${SECTION_SCHEMA}}. Verifica que summary, role e claims não contradizem o fragmento, distinguem tese de menções incidentais e que cada support_quote é literal. Se passed=false, devolve análise integral corrigida apenas com o fragmento; se true, repete sem alterações. Não inventes.`, profile: `Constrói uma ficha verificável de uma obra a partir das suas secções analisadas. Devolve JSON estrito: ${PROFILE_SCHEMA}. Kinds permitidos: object,problem,question,thesis,argument,method,sources,concept,temporal_scope,geographic_scope,disciplinary_scope,structure,conclusion,contribution,limitation,genre,audience,positioning,original_abstract. Inclui vários argument/concept quando necessário; omite o que não possa ser afirmado; cada afirmação requer apoio literal; não uses conhecimento externo.`, audit: `Audita uma ficha documental contra a estrutura e apoios literais. Devolve JSON estrito: ${AUDIT_SCHEMA}. Verifica tese, método, fontes, alcance, conclusões, centralidade e fidelidade de cada apoio. passed só pode ser true sem erros substanciais; não inventes.`, repair: `Repara a ficha usando apenas análises de secção e problemas do auditor. Devolve exatamente o esquema original. Remove campos sem apoio. Cada support_quote deve copiar sem alterar uma palavra um support_quote já presente em claims; não resumas, traduzas nem parafraseies.` },
  'pt-BR': { section: `Analise integralmente o fragmento de uma seção acadêmica. Retorne JSON estrito: ${SECTION_SCHEMA}. Copie a citação literalmente; diferencie o argumento central de menções incidentais; não invente.`, reduce: `Una análises parciais de UMA seção. Retorne o mesmo JSON estrito. Preserve somente afirmações centrais e citações literais já presentes; não invente citações.`, sectionAudit: `Audite uma análise de seção contra o fragmento completo. Retorne JSON estrito: {"passed":true,"issues":[""],"analysis":${SECTION_SCHEMA}}. Verifique que summary, role e claims não contradigam o fragmento, diferenciem tese de menções incidentais e que cada support_quote seja literal. Se passed=false, retorne análise completa corrigida usando só o fragmento; se true, repita sem alterações. Não invente.`, profile: `Construa uma ficha verificável de uma obra a partir de suas seções analisadas. Retorne JSON estrito: ${PROFILE_SCHEMA}. Kinds permitidos: object,problem,question,thesis,argument,method,sources,concept,temporal_scope,geographic_scope,disciplinary_scope,structure,conclusion,contribution,limitation,genre,audience,positioning,original_abstract. Inclua vários argument/concept quando necessário; omita o que não puder ser afirmado; toda afirmação requer apoio literal; não use conhecimento externo.`, audit: `Audite uma ficha documental contra sua estrutura e apoios literais. Retorne JSON estrito: ${AUDIT_SCHEMA}. Verifique tese, método, fontes, escopo, conclusões, centralidade e fidelidade de cada apoio. passed só pode ser true sem erros substanciais; não invente.`, repair: `Repare a ficha usando exclusivamente análises de seção e problemas do auditor. Retorne exatamente o esquema original. Remova campos sem apoio. Cada support_quote deve copiar, sem alterar uma palavra, um support_quote presente em claims; não resuma, traduza nem parafraseie.` },
  it: { section: `Analizza integralmente il frammento di una sezione accademica. Restituisci JSON rigoroso: ${SECTION_SCHEMA}. Copia la citazione letteralmente; distingui l’argomento centrale dalle menzioni incidentali; non inventare.`, reduce: `Unisci le analisi parziali di UNA sezione. Restituisci lo stesso JSON rigoroso. Conserva solo affermazioni centrali e citazioni letterali già presenti; non inventare citazioni.`, sectionAudit: `Verifica un’analisi di sezione contro il frammento completo. Restituisci JSON rigoroso: {"passed":true,"issues":[""],"analysis":${SECTION_SCHEMA}}. Controlla che summary, role e claims non contraddicano il frammento, distinguano la tesi dalle menzioni incidentali e che ogni support_quote sia letterale. Se passed=false, restituisci un’analisi completa corretta usando solo il frammento; se true, ripeti senza modifiche. Non inventare.`, profile: `Costruisci una scheda verificabile di un’opera dalle sezioni analizzate. Restituisci JSON rigoroso: ${PROFILE_SCHEMA}. Kinds consentiti: object,problem,question,thesis,argument,method,sources,concept,temporal_scope,geographic_scope,disciplinary_scope,structure,conclusion,contribution,limitation,genre,audience,positioning,original_abstract. Includi più campi argument/concept quando opportuno; ometti ciò che non è sostenibile; ogni affermazione richiede supporto letterale; nessuna conoscenza esterna.`, audit: `Verifica una scheda documentale contro struttura e supporti letterali. Restituisci JSON rigoroso: ${AUDIT_SCHEMA}. Controlla tesi, metodo, fonti, portata, conclusioni, centralità e fedeltà di ogni supporto. passed può essere true solo senza errori sostanziali; non inventare.`, repair: `Ripara la scheda usando solo analisi di sezione e problemi dell’auditor. Restituisci esattamente lo schema originale. Elimina campi non supportati. Ogni support_quote deve copiare senza modifiche un support_quote presente in claims; non riassumerlo, tradurlo o parafrasarlo.` },
  tr: { section: `Akademik bir bölüm parçasını bütünüyle analiz edin. Şu biçimde katı JSON döndürün: ${SECTION_SCHEMA}. Alıntıyı birebir kopyalayın; ana argümanı ikincil değinilerden ayırın; hiçbir şey uydurmayın.`, reduce: `TEK bir bölümün kısmi analizlerini birleştirin. Aynı katı JSON’u döndürün. Yalnızca merkezi iddiaları ve zaten mevcut birebir alıntıları koruyun; alıntı uydurmayın.`, sectionAudit: `Bölüm analizini onu destekleyen tam parçaya göre denetleyin. Şu biçimde katı JSON döndürün: {"passed":true,"issues":[""],"analysis":${SECTION_SCHEMA}}. summary, role ve claims parçayla çelişmemeli, tezi ikincil değinilerden ayırmalı ve her support_quote birebir olmalıdır. passed=false ise yalnızca parçayı kullanarak eksiksiz düzeltilmiş analiz döndürün; true ise alınan analizi değiştirmeden tekrarlayın. Uydurmayın.`, profile: `Analiz edilmiş bölümlerden doğrulanabilir bir eser profili oluşturun. Şu biçimde katı JSON döndürün: ${PROFILE_SCHEMA}. İzin verilen kinds: object,problem,question,thesis,argument,method,sources,concept,temporal_scope,geographic_scope,disciplinary_scope,structure,conclusion,contribution,limitation,genre,audience,positioning,original_abstract. Gerektiğinde birden çok argument/concept alanı ekleyin; desteklenmeyeni çıkarın; her iddianın birebir desteği olmalı; dış bilgi kullanmayın.`, audit: `Belge profilini yapısı ve birebir destekleriyle denetleyin. Şu biçimde katı JSON döndürün: ${AUDIT_SCHEMA}. Merkezi tez, yöntem, kaynaklar, kapsam, sonuçlar, ikincil değinilere karşı merkezilik ve her desteğin sadakatini kontrol edin. passed yalnızca esaslı hata yoksa true olabilir; uydurmayın.`, repair: `Profili yalnızca bölüm analizleri ve denetçi sorunlarını kullanarak onarın. Tam olarak özgün şemayı döndürün. Desteksiz alanları çıkarın. Her support_quote, claims içinde zaten bulunan bir support_quote değerini tek kelime değiştirmeden kopyalamalıdır; özetlemeyin, çevirmeyin veya yeniden ifade etmeyin.` },
};

