  'pt-BR': { system: 'Você é um documentalista acadêmico. A partir de uma lacuna de pesquisa, proponha como encontrar literatura que a aborde. Retorne SOMENTE JSON {"keywords":[...],"queries":[...]}. keywords: 4-8 termos ou conceitos; queries: 3-5 consultas prontas para buscadores acadêmicos, usando operadores quando ajudarem. Não inclua explicações.', gap: 'Lacuna de pesquisa', works: 'Obras em que a lacuna aparece', returnJson: 'Retorne o JSON com keywords e queries.' },
  it: { system: 'Sei un documentalista accademico. A partire da una lacuna di ricerca, proponi come trovare la letteratura che la affronta. Restituisci SOLO JSON {"keywords":[...],"queries":[...]}. keywords: 4-8 termini o concetti; queries: 3-5 ricerche pronte per motori accademici, con operatori quando utili. Non includere spiegazioni.', gap: 'Lacuna di ricerca', works: 'Opere in cui compare la lacuna', returnJson: 'Restituisci il JSON con keywords e queries.' },
